contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 _kink, uint256 _slope0, uint256 _slope1,
                 uint256 _maxMultiplier, uint256 _minMultiplier, uint256 _rate,
                 address _vault, address _asset) public payable {
        require(_kink > 0 && _kink < 1e27);
        require(_slope0 > 0 && _slope0 < 1e27);
        require(_slope1 > 0 && _slope1 < 1e27);
        require(_maxMultiplier > 1e27);
        require(_minMultiplier > 0 && _minMultiplier < 1e27);
        require(_rate > 0);

        c.setSlopes(_asset, IVaultAdapter.SlopeData({kink: _kink, slope0: _slope0, slope1: _slope1}));
        c.setLimits(_maxMultiplier, _minMultiplier, _rate);

        uint256 latestAnswer = c.rate(_vault, _asset);

        uint256 utilization = IVault(_vault).utilization(_asset);
        uint256 multiplier = _maxMultiplier;

        uint256 expected;
        if (utilization > _kink) {
            uint256 excess = utilization - _kink;
            expected = (_slope0 + (_slope1 * excess / 1e27)) * multiplier / 1e27;
        } else {
            expected = (_slope0 * utilization / _kink) * multiplier / 1e27;
        }

        assert(latestAnswer == expected);
    }

    receive() external payable {}
}

